import numpy as np
q=np.array([0.,.7585,1.]);v=np.array([.01245,0.,-.01245]);radius=.03;e=.095
for frame in range(96):
 if frame%8==0:print(frame,q.round(3),v.round(4))
 for _ in range(20):
  q+=v/20
  for i,j in [(0,1),(1,2)]:
   gap=q[j]-q[i]
   if gap<radius*2:
    d=(radius*2-gap)/2;q[i]-=d;q[j]+=d
    if v[i]>v[j]:
     mean=(v[i]+v[j])/2;diff=(v[i]-v[j])*e/2;v[i]=mean-diff;v[j]=mean+diff
  # damping, fitting slow separation in source after impact
  v*=np.exp(-.006/20)
PY"

